-- migration_48_app_recipes.sql
--
-- The recipes of the "Bateu Vontade?" app (/vontade), edited by Dolly in /admin/app-receitas.
--
--   app_recipes          one row per recipe. Everyone reads the FREE published ones in full; Tropical+ recipes
--                        are read in full only by Tropical+ members (is_tropical_plus) and admins. Only admins write.
--   is_tropical_plus()   true for a signed-in person with an active subscription or at least one paid box
--                        (my_journey().paid_boxes, the same count as the Clube Tropical stamps).
--   app_recipe_cards()   every published recipe's card (name, emoji, color, photo, cravings, time, what it needs),
--                        without ingredients or steps: the app ranks with it and shows a locked recipe as a teaser.
--
-- Seeded with the 28 launch recipes from src/lib/vontade.ts (generated by tools/vontade-seed.mjs). ON CONFLICT DO
-- NOTHING, so running this again never overwrites Dolly's edits.
--
-- Safe to run more than once. Until it runs, the app uses its built-in recipes and the admin page shows a
-- "rode a migration 48" hint. Run it BEFORE or right after the deploy; nothing else depends on it.

BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS public.app_recipes (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    slug          text UNIQUE NOT NULL CHECK (slug ~ '^[a-z0-9-]+$'),
    name          text NOT NULL,
    emoji         text NOT NULL DEFAULT '🍓',
    photo_url     text,
    -- One of the seven Sweet Escape colors (COLORS in lib/vontade.ts).
    color         text NOT NULL DEFAULT '#f7c600',
    -- chocolate | cremoso | fresquinho | crocante | salgadinho | umami | queijo | frito | refri | paoemassa
    cravings      text[] NOT NULL DEFAULT '{}',
    minutes       integer NOT NULL DEFAULT 5 CHECK (minutes BETWEEN 1 AND 120),
    -- Fridge or freezer time on top of the hands-on minutes.
    wait_minutes  integer NOT NULL DEFAULT 0 CHECK (wait_minutes BETWEEN 0 AND 1440),
    -- Pantry keys (PANTRY in lib/vontade.ts) the recipe can't do without.
    needs         text[] NOT NULL DEFAULT '{}',
    ingredients   text[] NOT NULL DEFAULT '{}',
    steps         text[] NOT NULL DEFAULT '{}',
    tip           text,
    -- Allergen ids from lib/allergens.ts.
    contains      text[] NOT NULL DEFAULT '{}',
    is_free       boolean NOT NULL DEFAULT false,
    published     boolean NOT NULL DEFAULT false,
    sort          integer NOT NULL DEFAULT 100,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION public.app_recipes_touch()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS app_recipes_touch ON public.app_recipes;
CREATE TRIGGER app_recipes_touch BEFORE UPDATE ON public.app_recipes
    FOR EACH ROW EXECUTE FUNCTION public.app_recipes_touch();

-- ------------------------------------------------------------ Tropical+
CREATE OR REPLACE FUNCTION public.is_tropical_plus()
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN false;
    END IF;
    IF EXISTS (SELECT 1 FROM public.subscriptions WHERE user_id = auth.uid() AND status IS DISTINCT FROM 'cancelled') THEN
        RETURN true;
    END IF;
    RETURN COALESCE((public.my_journey() ->> 'paid_boxes')::int, 0) >= 1;
END;
$$;
REVOKE ALL ON FUNCTION public.is_tropical_plus() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_tropical_plus() TO anon, authenticated;

-- ------------------------------------------------------------ who reads what
ALTER TABLE public.app_recipes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS app_recipes_read ON public.app_recipes;
CREATE POLICY app_recipes_read ON public.app_recipes
    FOR SELECT USING (
        (SELECT public.is_admin())
        OR (published AND (is_free OR (SELECT public.is_tropical_plus())))
    );
DROP POLICY IF EXISTS app_recipes_admin_write ON public.app_recipes;
CREATE POLICY app_recipes_admin_write ON public.app_recipes
    FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());

GRANT SELECT ON public.app_recipes TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.app_recipes TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.app_recipes TO service_role;

-- The cards of every published recipe, locked ones included, with no ingredients or steps.
CREATE OR REPLACE FUNCTION public.app_recipe_cards()
RETURNS TABLE (
    slug text, name text, emoji text, photo_url text, color text, cravings text[],
    minutes integer, wait_minutes integer, needs text[], is_free boolean, sort integer
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    SELECT r.slug, r.name, r.emoji, r.photo_url, r.color, r.cravings, r.minutes, r.wait_minutes, r.needs, r.is_free, r.sort
    FROM public.app_recipes r
    WHERE r.published
    ORDER BY r.sort, r.name;
$$;
REVOKE ALL ON FUNCTION public.app_recipe_cards() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.app_recipe_cards() TO anon, authenticated;

-- ------------------------------------------------------------ the launch recipes
INSERT INTO public.app_recipes
    (slug, name, emoji, color, cravings, minutes, wait_minutes, needs, ingredients, steps, tip, contains, is_free, published, sort)
VALUES
    ('brigadeiro-tamara', 'Brigadeiro de tâmara', '🍫', '#5a3421', ARRAY['chocolate', 'cremoso']::text[], 5, 0, ARRAY['tamara', 'cacau']::text[], ARRAY['5 tâmaras sem caroço', '1 colher (sopa) de cacau em pó puro', '1 colher (chá) de linhaça ou chia moída', 'cacau ou castanha moída para enrolar']::text[], ARRAY['Se as tâmaras estiverem duras, deixe 2 minutos em água quente e escorra.', 'Amasse com um garfo até virar uma pasta.', 'Misture o cacau e a linhaça até a massa ficar escura e brilhante.', 'Enrole 4 bolinhas e passe no cacau ou na castanha moída.']::text[], 'Guarde 2 na geladeira: amanhã, quando a vontade voltar, já está resolvido.', ARRAY['castanhas']::text[], true, true, 10),
    ('nice-cream-cacau', 'Sorvete de banana com cacau', '🍨', '#a33fc4', ARRAY['chocolate', 'cremoso', 'fresquinho']::text[], 3, 0, ARRAY['banana-congelada', 'cacau']::text[], ARRAY['2 bananas maduras congeladas em rodelas', '1 colher (sopa) de cacau em pó puro', '2 colheres (sopa) de leite vegetal sem açúcar (ou água)', 'frutas vermelhas por cima (opcional)']::text[], ARRAY['Bata tudo no processador ou liquidificador, parando para raspar as laterais.', 'Quando ficar liso como sorvete, pare. A banana já adoça tudo.', 'Coma na hora, com frutas vermelhas por cima se tiver.']::text[], 'Banana madura demais? Descasque, corte e congele. É o seu seguro anti-vontade.', ARRAY[]::text[], true, true, 20),
    ('manga-limao-chia', 'Manga com limão, hortelã e chia', '🥭', '#f7c600', ARRAY['fresquinho']::text[], 2, 0, ARRAY['manga']::text[], ARRAY['1 manga madura em cubos', 'raspas e umas gotas de ½ limão', '1 colher (chá) de chia', 'folhinhas de hortelã']::text[], ARRAY['Corte a manga em cubos numa tigela.', 'Rale a casca do limão por cima e esprema umas gotas.', 'Polvilhe a chia e finalize com a hortelã.']::text[], NULL, ARRAY[]::text[], true, true, 30),
    ('tamara-recheada', 'Tâmara recheada', '🌴', '#c9853c', ARRAY['crocante', 'chocolate']::text[], 2, 0, ARRAY['tamara', 'pasta-amendoim']::text[], ARRAY['3 tâmaras', '1 colher (sopa) de pasta de amendoim 100% amendoim', 'castanhas picadas ou uma pitada de cacau puro']::text[], ARRAY['Abra as tâmaras de um lado e tire o caroço.', 'Recheie com a pasta de amendoim.', 'Aperte por cima as castanhas picadas, ou polvilhe cacau.']::text[], 'Gelada fica com gosto de bombom: 10 minutos no congelador.', ARRAY['amendoim', 'castanhas']::text[], true, true, 40),
    ('banana-canela', 'Banana quentinha com canela', '🍌', '#ff7a1a', ARRAY['cremoso']::text[], 5, 0, ARRAY['banana']::text[], ARRAY['1 banana madura', 'canela em pó', '1 colher (sopa) de castanhas picadas ou sementes']::text[], ARRAY['Corte a banana ao meio, no comprido.', 'Doure numa frigideira antiaderente, sem nada, 2 minutos de cada lado.', 'Polvilhe canela e as castanhas ou sementes por cima.']::text[], NULL, ARRAY['castanhas']::text[], true, true, 50),
    ('mousse-abacate', 'Mousse de abacate e cacau', '🥑', '#27b35a', ARRAY['chocolate', 'cremoso']::text[], 5, 0, ARRAY['abacate', 'cacau', 'tamara']::text[], ARRAY['½ abacate bem maduro', '2 colheres (sopa) de cacau em pó puro', '3 tâmaras sem caroço', '3 colheres (sopa) de leite vegetal sem açúcar', 'frutas vermelhas para servir']::text[], ARRAY['Bata tudo no processador até ficar liso, sem nenhum pedacinho verde.', 'Prove: se quiser mais doce, mais uma tâmara.', 'Sirva num copinho com frutas vermelhas por cima.']::text[], 'Ninguém adivinha o abacate. Faça o teste com quem jura que não gosta.', ARRAY[]::text[], false, true, 60),
    ('beijinho-tamara', 'Beijinho de tâmara', '🥥', '#e8364f', ARRAY['cremoso']::text[], 5, 0, ARRAY['tamara', 'coco']::text[], ARRAY['5 tâmaras sem caroço', '1 colher (sopa) de castanha-de-caju moída', '1 colher (sopa) de coco ralado sem açúcar, para enrolar', '1 cravo por bolinha (opcional)']::text[], ARRAY['Amasse as tâmaras até virar pasta (2 minutos em água quente, se estiverem duras).', 'Misture a castanha moída.', 'Enrole, passe de leve no coco e espete um cravo, como na festa.']::text[], NULL, ARRAY['castanhas', 'coco']::text[], false, true, 70),
    ('sorvete-manga-maracuja', 'Sorvete de manga e maracujá', '🍧', '#f7c600', ARRAY['fresquinho', 'cremoso']::text[], 3, 0, ARRAY['manga-congelada', 'maracuja']::text[], ARRAY['1 xícara de manga congelada', 'polpa de 1 maracujá', '2 colheres (sopa) de água ou leite vegetal sem açúcar']::text[], ARRAY['Bata a manga com a água até ficar cremosa.', 'Coloque na tigela e regue com a polpa do maracujá, com as sementes.']::text[], NULL, ARRAY[]::text[], false, true, 80),
    ('maca-crocante', 'Rodelas de maçã crocantes', '🍎', '#e8364f', ARRAY['crocante', 'fresquinho']::text[], 3, 0, ARRAY['maca', 'pasta-amendoim']::text[], ARRAY['1 maçã', '1 colher (sopa) de pasta de amendoim 100% amendoim', 'castanhas picadas', '1 colher (chá) de linhaça', 'canela']::text[], ARRAY['Corte a maçã em rodelas grossas e tire o miolo com uma faquinha.', 'Espalhe a pasta de amendoim em cada rodela.', 'Cubra com castanhas, linhaça e canela. Coma como biscoito.']::text[], NULL, ARRAY['amendoim', 'castanhas']::text[], false, true, 90),
    ('crocante-frigideira', 'Crocante de castanhas e sementes', '🌻', '#c9853c', ARRAY['crocante']::text[], 5, 0, ARRAY['castanhas', 'sementes', 'tamara']::text[], ARRAY['½ xícara de castanhas picadas', '2 colheres (sopa) de sementes de girassol ou abóbora', '2 tâmaras picadinhas', 'canela']::text[], ARRAY['Toste as castanhas e as sementes numa frigideira seca, mexendo, por 3 a 4 minutos.', 'Desligue o fogo e misture as tâmaras e a canela: o calor gruda tudo.', 'Espalhe num prato: em 1 minuto fica crocante. Coma de colher ou por cima de uma fruta.']::text[], NULL, ARRAY['castanhas']::text[], false, true, 100),
    ('pudim-chia-cacau', 'Pudim de chia com cacau', '🥄', '#5a3421', ARRAY['chocolate', 'cremoso']::text[], 5, 120, ARRAY['chia', 'cacau', 'tamara', 'leite-vegetal']::text[], ARRAY['3 colheres (sopa) de chia', '1 xícara de leite vegetal sem açúcar', '1 colher (sopa) de cacau em pó puro', '2 tâmaras', 'frutas vermelhas para servir']::text[], ARRAY['Bata o leite, o cacau e as tâmaras no liquidificador.', 'Misture a chia num pote e mexa de novo depois de 5 minutos.', 'Leve à geladeira por 2 horas (ou a noite toda) e sirva com frutas vermelhas.']::text[], 'Faça 3 potes no domingo: a semana inteira fica resolvida.', ARRAY[]::text[], false, true, 110),
    ('geleia-frutas-vermelhas', 'Geleia rápida de frutas vermelhas', '🫐', '#a33fc4', ARRAY['fresquinho', 'cremoso']::text[], 5, 0, ARRAY['frutas-vermelhas', 'chia']::text[], ARRAY['1 xícara de frutas vermelhas (congeladas servem)', '1 colher (sopa) de chia', '1 banana em rodelas para servir']::text[], ARRAY['Aqueça as frutas numa panelinha por 3 minutos, amassando com o garfo.', 'Desligue e misture a chia: em 2 minutos engrossa.', 'Sirva morna sobre a banana. Não precisa de nada para adoçar.']::text[], NULL, ARRAY[]::text[], false, true, 120),
    ('trufa-caju', 'Trufa de caju e cacau', '🟫', '#a33fc4', ARRAY['chocolate', 'crocante']::text[], 5, 0, ARRAY['castanhas', 'tamara', 'cacau']::text[], ARRAY['½ xícara de castanhas-de-caju', '5 tâmaras sem caroço', '2 colheres (sopa) de cacau em pó puro']::text[], ARRAY['Triture as castanhas no processador até virar farofa.', 'Junte as tâmaras e o cacau e bata até a massa grudar.', 'Enrole bolinhas. Se quiser crocante, deixe pedacinhos de castanha.']::text[], NULL, ARRAY['castanhas']::text[], false, true, 130),
    ('grao-de-bico-crocante', 'Grão-de-bico crocante com limão e páprica', '🫘', '#ff7a1a', ARRAY['salgadinho', 'frito', 'crocante']::text[], 5, 25, ARRAY['grao-de-bico', 'limao']::text[], ARRAY['1 xícara de grão-de-bico cozido sem sal, bem escorrido', '1 colher (chá) de páprica defumada', '½ colher (chá) de alho em pó', 'raspas e suco de 1 limão']::text[], ARRAY['Seque bem o grão-de-bico num pano: quanto mais seco, mais crocante.', 'Espalhe numa assadeira com papel-manteiga, sem nada, e asse a 200 °C por 25 minutos (ou 15 na air fryer), sacudindo na metade.', 'Ainda quente, regue com o suco do limão e jogue as raspas, a páprica e o alho.', 'Espere 2 minutos: ele termina de ficar crocante fora do forno.']::text[], 'O limão faz o papel do sal. Prove antes de achar que falta alguma coisa.', ARRAY[]::text[], true, true, 140),
    ('pepino-limao', 'Pepino com limão, pimenta e gergelim', '🥒', '#27b35a', ARRAY['salgadinho', 'fresquinho']::text[], 2, 0, ARRAY['pepino', 'limao']::text[], ARRAY['1 pepino em rodelas ou palitos', 'suco de 1 limão', 'pimenta-do-reino ou calabresa em flocos', '1 colher (chá) de gergelim torrado', 'coentro ou cebolinha (opcional)']::text[], ARRAY['Corte o pepino e coloque numa tigela.', 'Esprema o limão, junte a pimenta e o gergelim e misture.', 'Deixe 1 minuto pegando gosto e coma gelado.']::text[], 'É o petisco de quem está tirando o sal: azedo, picante e crocante.', ARRAY['gergelim']::text[], true, true, 150),
    ('pacoca-cupuacu', 'Paçoca de cupuaçu e amendoim', '🥜', '#c9853c', ARRAY['salgadinho', 'crocante']::text[], 5, 0, ARRAY['amendoim', 'cupuacu']::text[], ARRAY['1 xícara de amendoim torrado sem sal e sem pele', '2 colheres (sopa) de polpa de cupuaçu sem açúcar', '2 tâmaras sem caroço', 'uma pitada de canela']::text[], ARRAY['Triture o amendoim no processador até virar farofa fina, sem deixar virar pasta.', 'Junte a polpa de cupuaçu e as tâmaras e pulse até a massa grudar quando apertada.', 'Prove: o azedinho do cupuaçu faz o papel do sal, e é ele que traz o gosto de paçoca.', 'Aperte num copinho ou forminha e desenforme.']::text[], 'Sem cupuaçu? Raspas e um pouco de suco de limão também acordam o amendoim.', ARRAY['amendoim']::text[], false, true, 160),
    ('cogumelo-tostado', 'Cogumelos tostados com alho e limão', '🍄', '#5a3421', ARRAY['umami', 'salgadinho']::text[], 5, 0, ARRAY['cogumelo', 'alho-cebola', 'limao']::text[], ARRAY['200 g de cogumelos (paris, shimeji ou shiitake) fatiados', '2 dentes de alho picados', 'suco de ½ limão', 'pimenta-do-reino e salsinha']::text[], ARRAY['Aqueça bem uma frigideira antiaderente, sem nada.', 'Espalhe os cogumelos e não mexa por 2 minutos: é assim que douram.', 'Mexa, junte o alho e deixe mais 1 minuto. Se grudar, uma colher de água.', 'Desligue, regue com o limão e finalize com pimenta e salsinha.']::text[], 'Sobre arroz integral ou dentro de uma folha de alface, vira "carne" de verdade.', ARRAY[]::text[], true, true, 170),
