    ('pate-cogumelo', 'Patê de cogumelo e nozes', '🫙', '#a33fc4', ARRAY['umami', 'queijo']::text[], 5, 0, ARRAY['cogumelo', 'castanhas', 'alho-cebola']::text[], ARRAY['200 g de cogumelos', '½ xícara de nozes ou castanhas', '1 dente de alho', 'suco de ½ limão', 'tomilho', 'palitos de cenoura e pepino para servir']::text[], ARRAY['Toste os cogumelos e o alho na frigideira seca até dourar.', 'Bata no processador com as nozes, o limão e o tomilho até ficar cremoso.', 'Sirva com palitos de legumes para mergulhar.']::text[], NULL, ARRAY['castanhas']::text[], false, true, 190),
    ('pipoca-levedura', 'Pipoca de panela seca com levedura', '🍿', '#f7c600', ARRAY['queijo', 'salgadinho', 'frito']::text[], 5, 0, ARRAY['milho-pipoca', 'levedura']::text[], ARRAY['¼ xícara de milho de pipoca', '2 colheres (sopa) de levedura nutricional', '½ colher (chá) de páprica', 'gotas de limão']::text[], ARRAY['Coloque o milho numa panela grande, seca e tampada, em fogo médio.', 'Quando começar a estourar, sacuda a panela de vez em quando até os estouros ficarem espaçados.', 'Passe para uma tigela, borrife umas gotas de limão (ajuda a grudar) e jogue a levedura e a páprica.']::text[], 'A levedura nutricional tem gosto de queijo: é ela que faz a mágica.', ARRAY[]::text[], true, true, 200),
    ('queijinho-caju', 'Queijinho de caju com limão', '🧀', '#ff7a1a', ARRAY['queijo', 'cremoso']::text[], 5, 0, ARRAY['castanhas', 'levedura', 'limao']::text[], ARRAY['1 xícara de castanha-de-caju crua, de molho por 2 horas (ou 10 minutos em água fervente)', '2 colheres (sopa) de levedura nutricional', 'suco de 1 limão', '½ dente de alho', '3 a 4 colheres (sopa) de água']::text[], ARRAY['Escorra a castanha.', 'Bata tudo no processador, raspando as laterais, até ficar liso e cremoso.', 'Prove e ajuste o limão: o azedinho é o que lembra queijo.', 'Sirva com palitos de legumes ou sobre batata-doce.']::text[], 'Na geladeira dura 4 dias e fica mais firme a cada dia.', ARRAY['castanhas']::text[], false, true, 210),
    ('molho-queijo-batata', 'Molho "de queijo" de batata e cenoura', '🥕', '#f7c600', ARRAY['queijo', 'paoemassa']::text[], 5, 15, ARRAY['batata', 'cenoura', 'castanhas', 'levedura']::text[], ARRAY['1 batata média em cubos', '1 cenoura em rodelas', '¼ xícara de castanha-de-caju', '2 colheres (sopa) de levedura nutricional', 'suco de ½ limão', '½ colher (chá) de alho em pó', 'água do cozimento']::text[], ARRAY['Cozinhe a batata e a cenoura em água por 15 minutos.', 'Bata no liquidificador com a castanha, a levedura, o limão, o alho e ½ xícara da água do cozimento.', 'Use sobre brócolis, batata ou macarrão integral, e leve ao forno para gratinar se quiser.']::text[], NULL, ARRAY['castanhas']::text[], false, true, 220),
    ('batata-doce-forno', 'Batata-doce rústica de forno', '🍠', '#ff7a1a', ARRAY['frito', 'paoemassa', 'salgadinho']::text[], 5, 30, ARRAY['batata']::text[], ARRAY['1 batata-doce grande com casca, em palitos grossos', '1 colher (chá) de páprica defumada', 'alecrim e alho em pó', 'limão para servir']::text[], ARRAY['Lave bem e corte em palitos, sem descascar.', 'Espalhe numa assadeira com papel-manteiga, sem nada, e tempere com páprica, alho e alecrim.', 'Asse a 220 °C por 30 minutos, virando na metade, até as pontas tostarem (ou 18 na air fryer).', 'Esprema limão por cima na hora de comer.']::text[], 'Com o guacamole vira o combo da batata frita com maionese.', ARRAY[]::text[], true, true, 230),
    ('guacamole', 'Guacamole com palitos crocantes', '🥑', '#27b35a', ARRAY['frito', 'salgadinho']::text[], 5, 0, ARRAY['abacate', 'limao', 'tomate']::text[], ARRAY['1 abacate maduro pequeno (ou ½ grande)', 'suco de 1 limão', '½ tomate picado', '¼ de cebola roxa picadinha', 'coentro e pimenta', 'palitos de cenoura, pepino e salsão']::text[], ARRAY['Amasse o abacate com o limão.', 'Junte o tomate, a cebola, o coentro e a pimenta.', 'Sirva com os palitos para mergulhar.']::text[], 'A gordura do abacate é o que a vontade de fritura procura, só que vem com fibra.', ARRAY[]::text[], false, true, 240),
    ('soda-maracuja', 'Soda de maracujá e limão', '🥤', '#a33fc4', ARRAY['refri', 'fresquinho']::text[], 2, 0, ARRAY['agua-gas', 'maracuja', 'limao']::text[], ARRAY['polpa de 1 maracujá', 'suco de ½ limão', '1 copo de água com gás bem gelada', 'gelo e folhas de hortelã']::text[], ARRAY['No copo, amasse a hortelã com o limão.', 'Junte a polpa do maracujá e o gelo.', 'Complete com a água com gás e mexa devagar.']::text[], 'Quer mais doce? Bata antes a polpa com 1 tâmara e um pouco de água.', ARRAY[]::text[], true, true, 250),
    ('cha-hibisco', 'Chá gelado de hibisco com frutas vermelhas', '🌺', '#e8364f', ARRAY['refri', 'fresquinho']::text[], 5, 30, ARRAY['frutas-vermelhas']::text[], ARRAY['2 colheres (sopa) de flor de hibisco seca', '1 litro de água', '1 xícara de frutas vermelhas', '1 pau de canela', 'limão e gelo']::text[], ARRAY['Ferva a água, desligue e coloque o hibisco e a canela. Tampe por 10 minutos.', 'Coe, junte as frutas vermelhas amassadas e leve à geladeira.', 'Sirva com muito gelo e rodelas de limão. Meio a meio com água com gás, vira refri.']::text[], NULL, ARRAY[]::text[], false, true, 260),
    ('panqueca-aveia', 'Panqueca de aveia e banana', '🥞', '#c9853c', ARRAY['paoemassa', 'cremoso']::text[], 5, 0, ARRAY['aveia', 'banana']::text[], ARRAY['1 banana madura', '½ xícara de aveia em flocos (sem glúten, se precisar)', '1 colher (sopa) de linhaça moída', '¼ xícara de leite vegetal sem açúcar', 'canela', 'frutas vermelhas para servir']::text[], ARRAY['Amasse a banana e misture com o resto até virar uma massa grossa.', 'Numa frigideira antiaderente bem quente, sem nada, coloque colheradas da massa.', 'Doure 2 minutos de cada lado, sem pressa para virar.', 'Sirva com frutas vermelhas por cima.']::text[], NULL, ARRAY['aveia']::text[], true, true, 270),
    ('batata-recheada', 'Batata-doce recheada com feijão e cogumelo', '🍠', '#a33fc4', ARRAY['paoemassa', 'umami']::text[], 5, 8, ARRAY['batata', 'feijao', 'cogumelo']::text[], ARRAY['1 batata-doce média', '½ xícara de feijão cozido sem sal (preto ou carioca)', '100 g de cogumelos picados', 'cebolinha, limão e pimenta']::text[], ARRAY['Fure a batata com um garfo e leve ao micro-ondas por 7 a 8 minutos, virando na metade (ou asse por 45 minutos).', 'Enquanto isso, toste os cogumelos na frigideira seca e junte o feijão para esquentar.', 'Abra a batata, recheie, esprema limão e finalize com cebolinha.']::text[], 'Feijão, cogumelo e batata-doce juntos: é o prato que mais acalma vontade.', ARRAY[]::text[], false, true, 280)
ON CONFLICT (slug) DO NOTHING;

COMMIT;

-- Verification: 28 recipes (12 free), and the public sees the free ones in full and every card.
SELECT count(*) AS recipes, count(*) FILTER (WHERE is_free) AS free, count(*) FILTER (WHERE published) AS published FROM public.app_recipes;
SELECT count(*) AS cards FROM public.app_recipe_cards();
